const ЗАГАДКИ = [{"з":"Сидит дед, во сто шуб одет. Кто его раздевает, тот слёзы проливает.","о":["лук","луковица"]},{"з":"Без окон, без дверей полна горница людей.","о":["огурец","огурцы"]},{"з":"Зимой и летом одним цветом.","о":["ёлка","ель","елка","сосна"]},{"з":"Висит груша — нельзя скушать.","о":["лампочка","лампа"]},{"з":"Не лает, не кусает, а в дом не пускает.","о":["замок"]},{"з":"Два кольца, два конца, а посередине гвоздик.","о":["ножницы"]},{"з":"Сто одёжек, и все без застёжек.","о":["капуста","кочан"]},{"з":"Сама в темнице, а коса на улице.","о":["морковь","морковка"]},{"з":"Не огонь, а жжётся.","о":["крапива"]},{"з":"Под землёй птица гнездо свила, яиц нанесла.","о":["картофель","картошка"]},{"з":"Маленький, удаленький, сквозь землю прошёл, красну шапочку нашёл.","о":["гриб","подосиновик","мухомор"]},{"з":"Стоит Алёна: платок зелёный, тонкий стан, белый сарафан.","о":["берёза","береза"]},{"з":"Летит — молчит, лежит — молчит, когда умрёт, тогда заревёт.","о":["снег"]},{"з":"Без рук, без ног, а ворота открывает.","о":["ветер"]},{"з":"Без рук, без топорика построена избушка.","о":["гнездо"]},{"з":"Течёт, течёт — не вытечет; бежит, бежит — не выбежит.","о":["река","речка"]},{"з":"Шёл долговяз, в землю увяз.","о":["дождь"]},{"з":"Красное коромысло через реку повисло.","о":["радуга"]},{"з":"Поле не мерено, овцы не считаны, пастух рогат.","о":["небо","звёзды","месяц","небо и звёзды"]},{"з":"Утром на четырёх ногах, днём на двух, вечером на трёх.","о":["человек"]},{"з":"Кто приходит, кто уходит, все её за ручку водят.","о":["дверь"]},{"з":"Всегда во рту, а не проглотишь.","о":["язык"]},{"з":"Два брата через дорогу живут, а друг друга не видят.","о":["глаза","глаз"]},{"з":"Пять братьев: годами равные, ростом разные.","о":["пальцы","палец"]},{"з":"Новая посуда, а вся в дырах.","о":["решето","сито","дуршлаг"]},{"з":"Маленький, кругленький, а за хвост не поднять.","о":["клубок","клубок ниток"]},{"з":"Кланяется, кланяется, придёт домой — растянется.","о":["топор"]},{"з":"Белый камушек растаял, на доске следы оставил.","о":["мел"]},{"з":"Чёрный конь скачет в огонь.","о":["кочерга"]},{"з":"Сам худ, голова с пуд.","о":["молоток","молот"]},{"з":"Рыжий Егорка упал на озёрко, сам не утонул и воды не всколыхнул.","о":["лист","листок","листик"]},{"з":"Сидит на ложке, свесив ножки.","о":["лапша"]},{"з":"Кругла, а не месяц, желта, а не масло, с хвостом, а не мышь.","о":["репа","репка"]},{"з":"На дворе горой, а в избе водой.","о":["снег"]},{"з":"Без досок, без топоров через речку мост готов.","о":["лёд","лед"]},{"з":"Зубов много, а ничего не ест.","о":["гребень","расчёска","расческа","грабли","пила"]},{"з":"Не море, не земля, корабли не плавают, а ходить нельзя.","о":["болото","трясина"]},{"з":"Что можно увидеть с закрытыми глазами?","о":["сон","сны"]},{"з":"Что в огне не горит и в воде не тонет?","о":["лёд","лед"]},{"з":"Кто говорит на всех языках?","о":["эхо"]},{"з":"Голова на ножке, в голове горошки.","о":["мак"]},{"з":"Стоит дуб, в нём двенадцать гнёзд, в каждом гнезде по четыре яйца.","о":["год"]},{"з":"Сер, да не волк, длинноух, да не заяц, с копытами, да не лошадь.","о":["осёл","осел","ишак"]},{"з":"Ног нет, а хожу; рта нет, а скажу, когда спать, когда вставать.","о":["часы","будильник"]},{"з":"Кто на себе свой дом носит?","о":["улитка","черепаха"]},{"з":"Хвостом виляет, зубаста, а не лает.","о":["щука"]},{"з":"Не портной, а всю жизнь с иголками ходит.","о":["ёж","еж","ёжик","ежик"]},{"з":"В воде купался, а сух остался.","о":["гусь","утка"]},{"з":"Под полом таится, кошки боится.","о":["мышь","мышка"]},{"з":"Мохнатенькая, усатенькая, молоко пьёт, песенки поёт.","о":["кошка","кот","киска"]},{"з":"С бородой, а не старик, с рогами, а не бык, доят, а не корова.","о":["коза"]},{"з":"Не зверь, не птица, а нос как спица.","о":["комар"]},{"з":"Всю жизнь ходят в обгонку, а обогнать друг друга не могут.","о":["ноги","колёса","колеса"]},{"з":"Чем больше из неё берёшь, тем больше она становится.","о":["яма"]},{"з":"Чёрный, да не ворон, рогат, да не бык.","о":["жук"]},{"з":"Сидит — зеленеет, падает — желтеет, лежит — чернеет.","о":["лист","листья"]},{"з":"Что можно приготовить, но нельзя съесть?","о":["уроки","урок","домашнее задание"]},{"з":"Какой рукой лучше размешивать чай?","о":["ложкой","ложка"]},{"з":"Что становится больше, если его поставить вверх ногами?","о":["6","шесть","шестёрка","шестерка"]},{"з":"У кого есть шапка без головы и нога без сапога?","о":["гриб"]},{"з":"Чем больше её моют, тем она становится грязнее.","о":["вода"]},{"з":"И блестит, и сверкает, никому не льстит, а любому правду скажет.","о":["зеркало"]},{"з":"Маленький шарик под лавкой шарит.","о":["мышь","мышка"]},{"з":"Без ног и без крыльев оно, быстро летит, не догонишь его.","о":["время"]},{"з":"Что идёт, не двигаясь с места?","о":["время","часы"]},{"з":"Синенькая шубенка весь мир покрыла.","о":["небо"]},{"з":"Крылья есть, а не летает; ног нет, а не догонишь.","о":["рыба"]},{"з":"Скатерть бела весь свет одела.","о":["снег"]},{"з":"Под одной крышей четыре брата стоят.","о":["стол"]},{"з":"Что выше леса, светлее света, а без огня горит?","о":["солнце"]},{"з":"Маленькое, кругленькое, до неба докинешь.","о":["глаз","глаза","взгляд"]},{"з":"Сколько горошин войдёт в пустой стакан?","о":["ни одной","нисколько","0","ноль"]}];
const СЛОВА = {"лёгкие":"абрикос,автобус,акула,апельсин,арбуз,бабочка,банан,барабан,башня,белка,берёза,библиотека,билет,блин,бутерброд,ванна,варенье,велосипед,вертолёт,ветер,вилка,виноград,вода,вокзал,волк,ворона,врач,газета,гитара,глаз,гнездо,гора,город,гриб,груша,гусь,дверь,дельфин,дерево,дождь,дорога,дракон,друг,дуб,ёжик,жираф,журнал,забор,заяц,звезда,зебра,зеркало,зима,змея,зонт,игрушка,капуста,карандаш,картина,картофель,каша,кенгуру,кино,кит,кошка,кровать,крокодил,кукла,лампа,лев,лес,лето,лимон,лиса,лодка,ложка,лошадь,луна,малина,мама,машина,медведь,мёд,мороженое,мост,мяч,нож,носок,обезьяна,облако,огурец,окно,орёл,осень,очки,пальто,папа,парк,паровоз,паук,пингвин,пирог,письмо,платье,повар,подарок,поезд,пожарный,помидор,попугай,праздник,пчела,рыба,ракета,река,робот,ромашка,рюкзак,самолёт,сапоги,сахар,свеча,слон,снеговик,снег,собака,солнце,стакан,стол,стул,сумка,сыр,танк,тарелка,телефон,торт,трамвай,тигр,утка,учитель,утюг,фонарь,футбол,хлеб,холодильник,цветок,цирк,чай,часы,чашка,черепаха,шапка,шар,шкаф,школа,шоколад,щенок,яблоко,ягода,яйцо,якорь","средние":"адрес,аптека,архитектор,аэропорт,балкон,баня,батарейка,бегемот,бинокль,бокал,будильник,буква,бумага,бухгалтер,вагон,ваза,веер,веник,весы,взрыв,вирус,витамин,водопад,вулкан,выставка,гараж,гвоздь,гербарий,гимнастика,глобус,гроза,губка,движение,диван,дирижёр,дневник,доктор,домино,дрель,душ,жемчуг,жилет,загадка,закат,зарплата,звонок,землетрясение,зоопарк,извержение,икра,инженер,кактус,календарь,камин,канат,капитан,карман,карусель,касса,каток,клавиатура,клей,кнопка,ковёр,колесо,колокол,компас,компьютер,конверт,конфета,корабль,корона,космонавт,костёр,кофе,кран,кроссовки,кружка,лабиринт,лавина,ладонь,лестница,лифт,магазин,магнит,маяк,медаль,метель,метро,микроскоп,миллионер,молния,музей,навигатор,наушники,ножницы,оркестр,остров,отпуск,палатка,парашют,паспорт,пенсия,перчатки,пианино,пират,пляж,подушка,полиция,почта,прыжок,пустыня,пылесос,радуга,ресторан,рецепт,рынок,светофор,секрет,сказка,скрипка,сосулька,спортсмен,стадион,страус,строитель,сугроб,таможня,театр,телескоп,термометр,тоннель,тренер,туман,улитка,урожай,фейерверк,фотограф,хоккей,храм,художник,цепочка,чемодан,чемпион,шахматы,шлем,штурвал,экзамен,эскалатор,юбилей,ярмарка","трудные":"авторитет,алгоритм,аллергия,амбиции,анекдот,аплодисменты,архив,аукцион,бюджет,бюрократия,вдохновение,велосипедист,вежливость,вечность,гармония,гипотеза,горизонт,гостеприимство,дедлайн,демократия,депрессия,дефицит,дипломатия,дисциплина,доверие,достоинство,дружба,ностальгия,забота,зависть,законопроект,занавес,интуиция,инфляция,ипотека,ирония,искренность,карьера,катастрофа,компромисс,конкуренция,контраст,кредит,кризис,лень,любопытство,мечта,мудрость,настроение,невесомость,независимость,ностальгия,обида,обязанность,одиночество,оптимизм,отпечаток,память,парадокс,пессимизм,победа,погода,поколение,популярность,похвала,презентация,привычка,принцип,противоречие,равновесие,расписание,реклама,репутация,революция,рефлекс,риск,самолюбие,свобода,сенсация,симпатия,скромность,совесть,сомнение,справедливость,стратегия,страх,судьба,сюрприз,талант,терпение,традиция,удача,упрямство,усталость,фантазия,философия,характер,хаос,храбрость,цензура,щедрость,эволюция,эгоизм,экономия,эмоция,энтузиазм,эпоха,юмор"};
const Ш = 560, В = 560, ФОН = '#f6f4ee', ТЕКСТ = '#22283a', ТУСК = '#7d8597', СИНИЙ = '#2f6fdf', ЗЕЛ = '#2b8a3e', КРАС = '#e03131', ЖЁЛТ = '#f08c00';
const ЙЦУКЕН = {KeyQ: 'й', KeyW: 'ц', KeyE: 'у', KeyR: 'к', KeyT: 'е', KeyY: 'н', KeyU: 'г', KeyI: 'ш', KeyO: 'щ', KeyP: 'з', BracketLeft: 'х', BracketRight: 'ъ',
  KeyA: 'ф', KeyS: 'ы', KeyD: 'в', KeyF: 'а', KeyG: 'п', KeyH: 'р', KeyJ: 'о', KeyK: 'л', KeyL: 'д', Semicolon: 'ж', Quote: 'э',
  KeyZ: 'я', KeyX: 'ч', KeyC: 'с', KeyV: 'м', KeyB: 'и', KeyN: 'т', KeyM: 'ь', Comma: 'б', Period: 'ю', Backquote: 'ё'};
const повод = () => (typeof книга !== 'undefined' && книга.повод) || (typeof документ !== 'undefined' && документ.повод) || {};
const норм = т => String(т || '').toLowerCase().replace(/ё/g, 'е').replace(/[^а-я0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const перемешать = м => { const а = м.slice(); for(let i = а.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [а[i], а[j]] = [а[j], а[i]]; } return а; };
const слова = уровень => (уровень === 'все' ? ['лёгкие', 'средние', 'трудные'] : [уровень]).flatMap(у => СЛОВА[у].split(',')).filter((x, i, а) => а.indexOf(x) === i);

let и = null, ввод = '', кнопки = [], часы = null;

/* ответ годится: совпал с вариантом или отличается только окончанием (для слов от пяти букв) */
function годится(ответ, варианты){
  const о = норм(ответ); if(!о) return false;
  for(const в of варианты.map(норм)){
    if(о === в) return true;
    if(в.length >= 5 && о.length >= 4){ const корень = в.slice(0, Math.max(4, в.length - 2)); if(о.startsWith(корень) && Math.abs(о.length - в.length) <= 2) return true; }
  }
  return false;
}

/* ---------- загадки ---------- */
function начатьЗагадки(){
  const решено = new Set(хранилище.взять('загадки', null) || []);
  const порядок = перемешать(ЗАГАДКИ.map((_, i) => i)).sort((a, b) => решено.has(a) - решено.has(b));
  и = {игра: 'Загадки', порядок, k: 0, отгадано: 0, попыток: 0, подсказка: 0, итог: null, сообщение: null, всего: 0};
  ввод = '';
}
const загадка = () => ЗАГАДКИ[и.порядок[и.k % и.порядок.length]];
function ответЗагадке(){
  if(и.итог){ следующаяЗагадка(); return; }
  if(!ввод.trim()) return;
  и.попыток++;
  const з = загадка();
  if(годится(ввод, з.о)){
    и.итог = 'верно'; и.отгадано++; и.всего++;
    const реш = хранилище.взять('загадки', null) || []; const n = и.порядок[и.k % и.порядок.length];
    if(!реш.includes(n)){ реш.push(n); хранилище.положить('загадки', реш); }
    и.сообщение = {текст: 'Верно! Это ' + з.о[0] + '.', цвет: ЗЕЛ};
    показатьСчёт();
  } else и.сообщение = {текст: и.попыток >= 3 ? 'Нет. Подсказка или «Сдаюсь»?' : 'Нет, не то. Ещё раз', цвет: КРАС};
  ввод = '';
}
function следующаяЗагадка(){ и.k++; и.итог = null; и.сообщение = null; и.попыток = 0; и.подсказка = 0; ввод = ''; }
function подсказкаЗагадки(){
  if(и.итог) return;
  const о = загадка().о[0]; и.подсказка = Math.min(о.length, и.подсказка + 1);
  и.сообщение = {текст: 'Подсказка: ' + о.slice(0, и.подсказка).toUpperCase() + '…  (' + о.length + ' ' + (о.length < 5 ? 'буквы' : 'букв') + ')', цвет: ЖЁЛТ};
}
function сдатьсяЗагадке(){ if(и.итог) return; и.итог = 'сдался'; и.всего++; и.сообщение = {текст: 'Ответ: ' + загадка().о[0], цвет: СИНИЙ}; }

/* ---------- анаграммы ---------- */
function начатьАнаграммы(уровень){
  const пул = перемешать(слова(уровень || 'средние').filter(с => с.length >= 5 && с.length <= 10 && !/[- ]/.test(с)));
  и = {игра: 'Анаграммы', пул, k: 0, отгадано: 0, серия: 0, лучшая: (хранилище.взять('анаграммы', null) || {}).серия || 0, итог: null, сообщение: null, открыто: 0, буквы: null};
  ввод = ''; новаяАнаграмма();
}
function новаяАнаграмма(){
  const с = и.пул[и.k % и.пул.length];
  let б; do { б = перемешать([...с]); } while(б.join('') === с && new Set(с).size > 1);
  и.буквы = б; и.итог = null; и.сообщение = null; и.открыто = 0; ввод = '';
}
const слово = () => и.пул[и.k % и.пул.length];
function ответАнаграмме(){
  if(и.итог){ и.k++; новаяАнаграмма(); return; }
  if(!ввод.trim()) return;
  if(норм(ввод) === норм(слово())){
    и.итог = 'верно'; и.отгадано++; и.серия++;
    if(и.серия > и.лучшая){ и.лучшая = и.серия; хранилище.положить('анаграммы', {серия: и.серия}); показатьСчёт(); }
    и.сообщение = {текст: 'Верно! ' + слово().toUpperCase() + (и.открыто ? '' : ' — без подсказок'), цвет: ЗЕЛ};
  } else if(норм(ввод).length === слово().length && [...норм(ввод)].sort().join('') === [...норм(слово())].sort().join('')) и.сообщение = {текст: 'Из этих букв, но загадано другое слово', цвет: ЖЁЛТ};
  else и.сообщение = {текст: 'Нет. Нужно слово из всех ' + слово().length + ' букв', цвет: КРАС};
  ввод = '';
}
function подсказкаАнаграммы(){ if(и.итог) return; и.открыто = Math.min(слово().length - 1, и.открыто + 1); и.серия = 0; и.сообщение = {текст: 'Начало: ' + слово().slice(0, и.открыто).toUpperCase() + '…', цвет: ЖЁЛТ}; }
function сдатьсяАнаграмме(){ if(и.итог) return; и.итог = 'сдался'; и.серия = 0; и.сообщение = {текст: 'Это было слово ' + слово().toUpperCase(), цвет: СИНИЙ}; }

/* ---------- объясни слово ---------- */
function начатьОбъясни(н){
  const имена = String(н.команды || '').split(',').map(x => x.trim()).filter(Boolean);
  const n = Math.max(2, Math.min(4, Math.round(+н.сколько || 2)));
  const команды = Array.from({length: n}, (_, i) => ({имя: имена[i] || 'Команда ' + (i + 1), очки: 0}));
  и = {игра: 'Объясни слово', команды, ход: 0, кругов: 0, пул: перемешать(слова(({'Лёгкие': 'лёгкие', 'Средние': 'средние', 'Трудные': 'трудные'})[н.сложность] || 'все')), k: 0,
    время: Math.max(15, Math.round(+н.время || 60)), цель: Math.max(5, Math.round(+н.цель || 30)), штраф: !!н.штраф, этап: 'ждём', слово: '', до: 0, раунд: [], победа: null};
}
function следующееСлово(){ и.слово = и.пул[и.k % и.пул.length]; и.k++; }
function начатьХод(){ и.этап = 'идёт'; и.раунд = []; и.до = Date.now() + и.время * 1000; следующееСлово(); }
function отметить(угадано){
  if(и.этап !== 'идёт') return;
  и.раунд.push({слово: и.слово, угадано});
  if(Date.now() >= и.до){ итогХода(); return; }
  следующееСлово();
}
function итогХода(){ и.этап = 'итог'; }
function очкиХода(){ return и.раунд.reduce((s, р) => s + (р.угадано ? 1 : (и.штраф ? -1 : 0)), 0); }
function закончитьХод(){
  const к = и.команды[и.ход];
  к.очки += очкиХода();
  и.ход = (и.ход + 1) % и.команды.length;
  if(и.ход === 0){
    и.кругов++;
    const лидер = Math.max(...и.команды.map(x => x.очки));
    if(лидер >= и.цель && и.команды.filter(x => x.очки === лидер).length === 1){ и.победа = и.команды.find(x => x.очки === лидер).имя; и.этап = 'конец'; return; }
  }
  и.этап = 'ждём';
}

