function перенос(текст, ширина, размер){
  const слова2 = String(текст).split(' '), out = []; let с = '';
  const дл = т => т.length * размер * 0.55;
  for(const w of слова2){ if(дл(с + ' ' + w) > ширина && с){ out.push(с); с = w; } else с = с ? с + ' ' + w : w; }
  if(с) out.push(с);
  return out;
}
