/* ---------- функции плагина ---------- */
function Старт(){ показатьСчёт(); }
function Играть(){
  const п = параметры({});
  const игра = п.игра || 'Загадки';
  if(игра === 'Анаграммы') начатьАнаграммы(({'Лёгкие': 'лёгкие', 'Средние': 'средние', 'Трудные': 'трудные'})[п.сложность] || 'средние');
  else if(игра === 'Объясни слово') начатьОбъясни(п);
  else начатьЗагадки();
  окно.открыть('игра', {});
  окно.в('игра').заголовок('Словесные игры — ' + игра);
  окно.в('игра').сообщение(игра === 'Объясни слово' ? 'Enter — угадали, → — пропустить. Объясняющий смотрит на экран, команда — нет.' : 'Щёлкните по окну и печатайте — раскладка не важна. Enter — ответить.');
  завестиЧасы();
  нарисовать();
}
function действие(имя){
  if(!и) return;
  if(и.игра === 'Загадки'){
    if(имя === 'ответ' || имя === 'дальше') ответЗагадке(); else if(имя === 'подсказка') подсказкаЗагадки(); else if(имя === 'сдаюсь') сдатьсяЗагадке();
  } else if(и.игра === 'Анаграммы'){
    if(имя === 'ответ' || имя === 'дальше') ответАнаграмме(); else if(имя === 'подсказка') подсказкаАнаграммы(); else if(имя === 'сдаюсь') сдатьсяАнаграмме();
  } else {
    if(имя === 'начать') начатьХод();
    else if(имя === 'угадали') отметить(true);
    else if(имя === 'пропуск') отметить(false);
    else if(имя === 'дальше') закончитьХод();
    else if(имя === 'заново') Играть();
    else if(/^слово\d+$/.test(имя)){ const р = и.раунд[+имя.slice(5)]; if(р) р.угадано = !р.угадано; }
  }
  нарисовать();
}
function Клавиша(){
  const к = повод();
  if(к.вид !== 'нажата' || !и) return;
  if(и.игра === 'Объясни слово'){
    if(к.клавиша === 'Enter' || к.клавиша === ' ') действие(и.этап === 'ждём' ? 'начать' : и.этап === 'идёт' ? 'угадали' : и.этап === 'итог' ? 'дальше' : 'заново');
    else if((к.клавиша === 'ArrowRight' || к.клавиша === 'Backspace') && и.этап === 'идёт') действие('пропуск');
    return;
  }
  if(к.клавиша === 'Enter') действие('ответ');
  else if(к.клавиша === 'Backspace') ввод = ввод.slice(0, -1);
  else if(/^[а-яё]$/i.test(к.клавиша)) ввод += к.клавиша.toLowerCase();
  else if(ЙЦУКЕН[к.код] && /^[a-z\[\];',.`]$/i.test(к.клавиша)) ввод += ЙЦУКЕН[к.код];
  else if(/^[0-9 -]$/.test(к.клавиша)) ввод += к.клавиша;
  if(ввод.length > 30) ввод = ввод.slice(0, 30);
  нарисовать();
}
function Мышь(){
  const м = повод();
  if(м.вид !== 'нажатие' || !и) return;
  const б = кнопки.slice().reverse().find(b => м.x >= b.x && м.x <= b.x + b.ш && м.y >= b.y && м.y <= b.y + b.в);
  if(б) действие(б.имя);
}
