function Состояние(){ if(!и) return null; const о = {игра: и.игра, ввод, сообщение: и.сообщение && и.сообщение.текст, итог: и.итог || null};
  if(и.игра === 'Загадки') Object.assign(о, {загадка: загадка().з, ответы: загадка().о, отгадано: и.отгадано});
